def lower_bound(a, target):
    left, right = 0, len(a)
    while left < right:
        mid = left + (right - left) // 2
        if a[mid] < target:
            left = mid + 1
        else:
            right = mid
    return left

def inversion_count(a):
    def solve(values):
        if len(values) <= 1:
            return values[:], 0
        mid = len(values) // 2
        left, x = solve(values[:mid])
        right, y = solve(values[mid:])
        merged, i, j, cross = [], 0, 0, 0
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                merged.append(left[i])
                i += 1
            else:
                merged.append(right[j])
                j += 1
                cross += len(left) - i
        merged.extend(left[i:])
        merged.extend(right[j:])
        return merged, x + y + cross
    return solve(list(a))[1]

import random

def kth_smallest(values, k, seed=0):
    a, rng = list(values), random.Random(seed)
    if not 1 <= k <= len(a):
        raise ValueError("invalid k")
    lo, hi, target = 0, len(a) - 1, k - 1
    while lo <= hi:
        pivot = a[rng.randrange(lo, hi + 1)]
        lt, i, gt = lo, lo, hi
        while i <= gt:
            if a[i] < pivot:
                a[lt], a[i] = a[i], a[lt]
                lt, i = lt + 1, i + 1
            elif a[i] > pivot:
                a[i], a[gt] = a[gt], a[i]
                gt -= 1
            else:
                i += 1
        if target < lt:
            hi = lt - 1
        elif target > gt:
            lo = gt + 1
        else:
            return pivot

reference_answer:
三路划分为小于、等于、大于枢轴的连续区间。若目标下标 k−1 落在等于区间，立即返回；否则只在可能包含目标的一侧继续。这样重复值不会造成错误或全相等输入下的不必要递归。

每轮划分线性；均匀随机枢轴以常数概率把区间缩小至至多原来的 3/4，从而总期望工作量为 O(n)，且读取输入给出 Ω(n) 下界。连续选到极端枢轴时仍可能 Θ(n²)。随机化保证针对任意固定输入的期望，不是每次最坏线性。

下面实现先复制输入，空间 O(n)；若允许直接修改原数组，迭代划分部分额外空间 O(1)。seed 用于复现实验，不应把固定种子误称为抗对抗输入的安全保证。

