def knapsack_01(items, capacity):
    dp = [0] * (capacity + 1)
    for weight, value in items:
        for c in range(capacity, weight - 1, -1):
            dp[c] = max(dp[c], dp[c - weight] + value)
    return dp[capacity]

def lcs_length(x, y):
    if len(x) < len(y):
        x, y = y, x
    previous = [0] * (len(y) + 1)
    for char_x in x:
        current = [0] * (len(y) + 1)
        for j, char_y in enumerate(y, 1):
            if char_x == char_y:
                current[j] = previous[j - 1] + 1
            else:
                current[j] = max(previous[j], current[j - 1])
        previous = current
    return previous[-1]

reference_answer:
令 dp[i][j] 为 x 前 i 个字符与 y 前 j 个字符的最优长度，空前缀对应 0。末字符相同时，可取左上状态加 1；不同时，至少舍弃一个末字符，取上方与左方的最大值。按前缀长度递增填表。

恢复时从 (m,n) 回溯：相等字符加入答案并对角移动，否则往值较大的一侧移动；同值可任选，最后反转。此方法得到一条解，不保证字典序最小，也不枚举所有解。

