def matrix_chain_cost(p):
    n = len(p) - 1
    dp = [[0] * n for _ in range(n)]
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = min(
                dp[i][k] + dp[k + 1][j] + p[i] * p[k + 1] * p[j + 1]
                for k in range(i, j)
            )
    return dp[0][n - 1]

import heapq

def dijkstra(adj, source):
    dist = [float("inf")] * len(adj)
    dist[source] = 0
    heap = [(0, source)]
    while heap:
        distance, u = heapq.heappop(heap)
        if distance != dist[u]:
            continue
        for v, weight in adj[u]:
            candidate = distance + weight
            if candidate < dist[v]:
                dist[v] = candidate
                heapq.heappush(heap, (candidate, v))
    return dist

from collections import deque

def earliest_completion(duration, adj):
    indegree = [0] * len(adj)
    for edges in adj:
        for v in edges:
            indegree[v] += 1
    queue = deque(i for i, d in enumerate(indegree) if d == 0)
    finish, seen = list(duration), 0
    while queue:
        u = queue.popleft()
        seen += 1
        for v in adj[u]:
            finish[v] = max(finish[v], finish[u] + duration[v])
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)
    if seen != len(adj):
        raise ValueError("cyclic dependencies")
    return max(finish, default=0)

reference_answer:
在拓扑过程中令 finish[v] 初值为自身耗时。处理边 u→v 时更新 finish[v]=max(finish[v],finish[u]+duration[v])，对应等待所有前置任务的最晚结束。所有顶点处理完后取最大 finish。空图约定为 0。

拓扑序保证计算 v 前所有前驱已确定，因而按序归纳正确。例中 A、B 同时开始，C 在时刻 3 开始、7 结束，D 在 9 结束。若处理顶点数少于 n，则存在环，当前依赖要求不能完成，不能返回部分计算结果。

每个顶点和边各处理一次，时间 O(n+m)，辅助空间 O(n)。一般图最长简单路径并无这样的高效保证；此处依靠 DAG 结构与无限并行资源假设。若只有一台机器，模型需要改变。

