def kruskal_weight(n, edges):
    parent, size = list(range(n)), [1] * n
    def find(x):
        while x != parent[x]:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    total = used = 0
    for u, v, weight in sorted(edges, key=lambda edge: edge[2]):
        a, b = find(u), find(v)
        if a == b:
            continue
        if size[a] < size[b]:
            a, b = b, a
        parent[b] = a
        size[a] += size[b]
        total, used = total + weight, used + 1
    if used != n - 1:
        raise ValueError("disconnected graph")
    return total

def kmp_find(text, pattern):
    if not pattern:
        return 0
    pi = [0] * len(pattern)
    for i in range(1, len(pattern)):
        j = pi[i - 1]
        while j and pattern[i] != pattern[j]:
            j = pi[j - 1]
        if pattern[i] == pattern[j]:
            j += 1
        pi[i] = j
    j = 0
    for i, char in enumerate(text):
        while j and char != pattern[j]:
            j = pi[j - 1]
        if char == pattern[j]:
            j += 1
        if j == len(pattern):
            return i - j + 1
    return -1

reference_answer:
pi[i] 表示模式前缀 pattern[0:i+1] 的最长真前缀与后缀的公共长度；本例为 [0,0,1,2,3,0]。失配时令 j=pi[j−1]，保留已经确认与文本后缀相等的较短前缀。比这更长的候选因失配已被排除。

构造 pi 和扫描文本都使用同样的退回逻辑。每轮外层使位置向前；j 的增加次数为线性，回退只消耗此前增加形成的额度，因此 while 虽然嵌套，累计次数仍线性。

设文本长 n、模式长 m，时间 O(n+m)，辅助空间 O(m)。返回首次完整匹配的位置。不能把 pi 当作“已经匹配的字符总数”跨失配无条件保留，也不应在每次失配后重新扫描整个模式。

