def subset_sum_exists(a, target):
    n = len(a)
    suffix = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix[i] = suffix[i + 1] + a[i]
    def search(i, total):
        if total == target:
            return True
        if i == n or total > target or total + suffix[i] < target:
            return False
        return search(i + 1, total + a[i]) or search(i + 1, total)
    return search(0, 0)
```
